"""Generate reports from saved results, without further model fitting."""
from run import *
def table(headers,rows):
    def cell(v):return str(v).replace('|','\\|').replace('\n','<br>')
    return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(cell(v) for v in row)+' |' for row in rows])
def md(name,text):(OUT/name).write_text('\n'.join(x.rstrip() for x in text.splitlines()).rstrip()+'\n',encoding='utf8')
def main():
    import numpy as np
    protected();a=read('corpus_audit_summary.json');s=read('paired_style_summary.json');cv=records(OUT/'cv_summary.csv');fixed=records(OUT/'paired_fixed_model_results.csv');stability=records(OUT/'paired_training_resample_stability.csv');authors=records(OUT/'corpus_by_author.csv');lengths=records(OUT/'development_lengths_and_dates.csv')
    core=[r for r in cv if r['cohort']=='train_all_annotations'];primary=[r for r in fixed if r['pool']=='all_train_excluding_pairs']
