    paired_table=table(['method','Original accuracy','Rewrite accuracy','Original F1','Rewrite F1','delta accuracy','p exact','p Holm'],[[r['method'],f"{100*float(r['accuracy_original']):.2f}%",f"{100*float(r['accuracy_rewrite']):.2f}%",f"{float(r['macro_f1_original']):.4f}",f"{float(r['macro_f1_rewrite']):.4f}",f"{100*float(r['accuracy_delta']):+.2f}pp",f"{float(r['mcnemar_exact_p']):.5f}",f"{float(r['holm_primary_p']):.5f}"] for r in primary])
    corpus='# איכות המאגר וגבולות השימוש\n\nמחזור עבודה 8–9 בנובמבר 2026. ניתוחי תוכן/features חדשים בוצעו רק בכותבי train. עבור val/test נבדקו מיפוי כותבים, ספירות ו־hashes קיימים; לא בוצעה עליהם בחירת שיטה, למידה או הערכת מודל.\n\n'
    corpus+=table(['scope','train','validation','test','total'],[['unique annotated sources',202,96,131,429],['two-narrative eligible sources',105,43,70,218],['authors',9,4,6,19],['ChatGPT pairs',30,0,0,30]])+'\n\n'
    corpus+='## מה נספר\n\n456 רשומות נאספו מ־19 כותבים; יש בהן 429 text hashes שונים. לאחר הסרת חזרות נשמרו 429 קטעים מ־429 מאמרים שונים. v2/v3/ChatGPT הם גרסאות של מקורות קיימים, ולא מאות מאמרים חדשים. אין לחבר את שורות קובצי הניסויים כדי לאמוד גודל קורפוס. [Source inventory](source_inventory.csv).\n\n'
    corpus+='בכל 429 הרשומות יש byline_verified=True: זוהי ראיית ייחוס פומבי, לא אימות אנושי לתווית הנרטיב ולא הוכחה לכתיבה ללא עורכים/עזרה. אין תוויות מקור אנושיות שמולאו: 0/429; גם חבילת המקור האנושית נבדקה ונמצאה ריקה. התוויות הן הצעות מכונה: '+', '.join(k+'='+str(v) for k,v in a['machine_label_distribution'].items())+'. 218 טקסטים נבחרו לתת־משימה Right-wing/Left-wing; 211 אחרים אינם הופכים אוטומטית לתווית בינארית. זה אינו קורפוס מאומת לכל שבעת הנרטיבים.\n\n'
